<?php
declare(strict_types=1);

function community_people(): array
{
    return query_all("SELECT u.id,u.username,u.display_name FROM users u JOIN user_app_access a ON a.user_id=u.id AND a.app_code='comunidad' WHERE u.active=1 ORDER BY FIELD(LOWER(u.username),'chiara','nanay','martin','sergio'),u.display_name");
}

function community_user_name(?int $id): string
{
    if (!$id) return 'Comunidad';
    $row=query_one('SELECT display_name FROM users WHERE id=?',[$id]);
    return (string)($row['display_name']??'Comunidad');
}

function community_log(int $activityId,int $userId,string $action,?string $details=null): void
{
    execute_sql('INSERT INTO community_activity_logs (activity_id,user_id,action,details) VALUES (?,?,?,?)',[$activityId,$userId,$action,$details]);
}

function community_complete_purchase(int $planId,int $userId,?int $paidBy,string $scope): array
{
    $pdo=db();$pdo->beginTransaction();
    try{
        $plan=query_one('SELECT * FROM community_purchase_plans WHERE id=? FOR UPDATE',[$planId]);
        if(!$plan) throw new RuntimeException('La compra no existe.');
        if(($plan['status']??'pendiente')==='realizada') throw new RuntimeException('La compra ya fue realizada.');
        $items=query_all('SELECT * FROM community_purchase_items WHERE plan_id=? ORDER BY id FOR UPDATE',[$planId]);
        if(!$items) throw new RuntimeException('Agregue al menos un elemento.');
        $created=0;
        foreach($items as $item){
            $qty=max(1,(int)round((float)$item['quantity']));$units=min($qty,500);
            for($i=1;$i<=$units;$i++){
                $notes='Creado desde la compra comunitaria '.$plan['title'].'.';
                if($units>1)$notes.=" Unidad {$i} de {$units}.";
                if($item['purchase_place'])$notes.=' Lugar: '.$item['purchase_place'].'.';
                if($item['notes'])$notes.=' '.$item['notes'];
                execute_sql("INSERT INTO community_materials (name,category,owner_user_id,status,hive_id,notes,source_purchase_plan_id,source_purchase_item_id,created_by_user_id) VALUES (?,'Otros materiales',NULL,'disponible',NULL,?,?,?,?)",[$item['item_name'],$notes,$planId,(int)$item['id'],$userId]);
                $created++;
            }
            execute_sql('UPDATE community_purchase_items SET is_purchased=1 WHERE id=?',[(int)$item['id']]);
        }
        execute_sql("UPDATE community_purchase_plans SET status='realizada',completed_by_user_id=?,paid_by_user_id=?,expense_scope=?,completed_at=NOW(),materials_generated_at=NOW() WHERE id=?",[$userId,$paidBy,$scope,$planId]);
        $pdo->commit();return ['materials_created'=>$created];
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}

function community_backup_sql(array $tables): string
{
    $out="SET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n\n";
    foreach($tables as $table){
        if(!table_exists($table))continue;
        if(in_array($table,['management_calendar_events','queen_rearing_batches'],true)){
            $out.="DELETE FROM `{$table}` WHERE `app_code`='comunidad';\n";
            $rows=query_all("SELECT * FROM `{$table}` WHERE app_code='comunidad'");
        }else{
            $create=query_one("SHOW CREATE TABLE `{$table}`");
            $key='Create Table';
            $out.="DROP TABLE IF EXISTS `{$table}`;\n".($create[$key]??'').";\n";
            $rows=query_all("SELECT * FROM `{$table}`");
        }
        foreach($rows as $row){
            $cols=array_map(fn($c)=>'`'.str_replace('`','``',$c).'`',array_keys($row));
            $vals=array_map(function($v){if($v===null)return 'NULL';return db()->quote((string)$v);},array_values($row));
            $out.='INSERT INTO `'.$table.'` ('.implode(',',$cols).') VALUES ('.implode(',',$vals).");\n";
        }
        $out.="\n";
    }
    return $out."SET FOREIGN_KEY_CHECKS=1;\n";
}

