            $type=trim((string)($_GET['type']??''));$id=(int)($_GET['id']??0);$row=null;$inline=true;if($type==='hive')$row=query_one('SELECT original_name,relative_path,mime_type FROM community_hive_photos WHERE id=?',[$id]);elseif($type==='material')$row=query_one('SELECT photo_original_name original_name,photo_relative_path relative_path,photo_mime_type mime_type FROM community_materials WHERE id=?',[$id]);elseif($type==='activity')$row=query_one('SELECT original_name,relative_path,mime_type FROM community_activity_attachments WHERE id=?',[$id]);elseif($type==='inspection')$row=query_one('SELECT original_name,relative_path,mime_type FROM community_hive_inspection_files WHERE id=?',[$id]);elseif($type==='receipt')$row=query_one('SELECT receipt_original_name original_name,receipt_relative_path relative_path,receipt_mime_type mime_type FROM community_accounting_entries WHERE id=?',[$id]);elseif($type==='personal_receipt')$row=query_one('SELECT receipt_original_name original_name,receipt_relative_path relative_path,receipt_mime_type mime_type FROM community_personal_accounting_entries WHERE id=? AND owner_user_id=?',[$id,$uid]);elseif($type==='backup'){$row=query_one("SELECT filename original_name,CONCAT('storage/backups/',filename) relative_path,'application/zip' mime_type FROM community_backup_history WHERE id=? AND created_by_user_id=?",[$id,$uid]);$inline=false;}if(!$row||empty($row['relative_path']))api_fail('El archivo no existe.',404);$rel=str_replace('\\','/',$row['relative_path']);if(str_contains($rel,'../')||!str_starts_with($rel,'storage/'))api_fail('Ruta inválida.');api_send_file(dirname(__DIR__).'/'.$rel,(string)$row['original_name'],(string)$row['mime_type'],$inline);

        default:api_fail('Acción comunitaria desconocida.',404);
